bundle<-Sys.getenv("ICCA_BUNDLE_ROOT");stopifnot(nzchar(bundle));result<-Sys.getenv("ICCA_FINALIZATION_OUTPUT_ROOT");stopifnot(nzchar(result));dir.create(file.path(result,"figures/panels"),recursive=TRUE,showWarnings=FALSE);dir.create(file.path(result,"review"),recursive=TRUE,showWarnings=FALSE)
suppressPackageStartupMessages({library(data.table);library(ggplot2);library(patchwork);library(grid);library(svglite);library(ragg)})
o<-result;ff<-file.path(o,'figures/panels');tt<-file.path(bundle,'source_data/display_fix_inputs');grDevices::pdfFonts(Arial=grDevices::pdfFonts('Helvetica')[[1]])
read<-function(n)fread(file.path(tt,paste0(n,'.csv')));eff<-read('program_effects');sm<-read('E_summary');pr<-read('projection_labels');del<-read('paired_differences')[Metric=='BalancedAccuracy'];ch<-read('choice');INK<-'#293F50';pal<-c(C1='#0072B2',C2='#E69F00',C3='#CC79A7')
cohs<-sort(unique(eff$Cohort));short<-setNames(c('Andersen','Sia','Jus P1','Jus P2','Job','TIGER'),cohs);programs<-unique(eff$Program);programs<-c('HALLMARK_BILE_ACID_METABOLISM','HALLMARK_FATTY_ACID_METABOLISM','HALLMARK_OXIDATIVE_PHOSPHORYLATION','HALLMARK_NOTCH_SIGNALING','HALLMARK_E2F_TARGETS','HALLMARK_G2M_CHECKPOINT','HALLMARK_HYPOXIA','HALLMARK_GLYCOLYSIS','HALLMARK_EPITHELIAL_MESENCHYMAL_TRANSITION');labs<-c('Bile-acid metabolism','Fatty-acid metabolism','Oxidative phosphorylation','Notch signaling','E2F targets','G2M checkpoint','Hypoxia','Glycolysis','EMT')
stopifnot(all(eff$Program%in%programs));eff[,ProgramLabel:=factor(Program,levels=rev(programs),labels=rev(labs))];eff[,CohortLabel:=factor(short[Cohort],levels=unname(short))];stopifnot(!anyNA(eff$CohortLabel),!anyNA(eff$ProgramLabel))
th<-function(){theme_classic(base_size=8,base_family='Arial')+theme(plot.title=element_text(size=7,face='bold',colour=INK),plot.subtitle=element_text(size=6),plot.title.position='plot',plot.caption=element_text(size=5.8,hjust=0,colour='grey30',lineheight=1.1),plot.caption.position='plot',axis.title=element_text(size=6),axis.text=element_text(size=5.8,colour='grey20'),axis.line=element_line(linewidth=.3,colour='grey45'),axis.ticks=element_line(linewidth=.25),legend.text=element_text(size=5.8),legend.title=element_text(size=6),legend.key.size=unit(3,'mm'),legend.position='top',strip.background=element_rect(fill='#EAF0F4',colour=NA),strip.text=element_text(size=8,face='bold'),panel.spacing=unit(4,'mm'),plot.margin=margin(1.5,1.5,1.5,1.5,'mm'))}
vt<-function(t,x,y,size=6,bold=F,just='left',col=INK){grid.text(t,unit(x,'native'),unit(y,'native'),just=just,gp=gpar(fontfamily='Arial',fontsize=size,fontface=if(bold)'bold'else'plain',col=col,lineheight=1.05))};vr<-function(x,y,w,h,col){grid.rect(unit(x,'native'),unit(y,'native'),unit(w,'native'),unit(h,'native'),gp=gpar(fill=col,col=NA))};vl<-function(x,y,col=INK,lwd=.5){grid.lines(unit(x,'native'),unit(y,'native'),gp=gpar(col=col,lwd=lwd))};vp<-function(x,y,size=.8){grid.points(unit(x,'native'),unit(y,'native'),pch=16,size=unit(size,'mm'),gp=gpar(col=INK))};canvas<-function(w,h){grid.newpage();pushViewport(viewport(xscale=c(0,w),yscale=c(0,h)))}
summary<-function(){canvas(174,17);vt('Projected counts',1,4.2,5.7,T);vt('n; genes / 114',1,10,5.7);for(i in 1:6){z<-sm[CohortOrder==i];x<-36+(i-1)*24.6;vt(short[i],x,14.4,6,T,'centre');vt(sprintf('%d; %d/114',z$N,z$MatchedFeatures),x,10,5.5,F,'centre');cum<-0;for(j in 1:3){n<-nrow(pr[Cohort==z$Cohort&Prediction==paste0('C',j)]);wid<-22*n/z$N;vr(x-11+cum+wid/2,4.2,wid,3,pal[j]);vt(n,x-11+cum+wid/2,4.2,5.3,F,'centre',if(j==2)INK else'white');cum<-cum+wid}};popViewport()}
lim<-ceiling(max(abs(eff$G),na.rm=T)*2)/2
heat<-ggplot(eff[Scenario=='Exclude114'],aes(CohortLabel,ProgramLabel,fill=G))+geom_tile(colour='white',linewidth=.35)+facet_wrap(~Class,nrow=1)+scale_fill_gradient2(low='#377EB8',mid='white',high='#CD5258',midpoint=0,limits=c(-lim,lim),name='Hedges g',na.value='#B7B7B7',guide=guide_colorbar(display='rectangles'))+labs(title='Frozen programs after classifier-gene exclusion',x=NULL,y=NULL)+th()+theme(axis.line=element_blank(),axis.ticks=element_blank(),axis.text.x=element_text(size=5.8,angle=40,hjust=1),axis.text.y=element_text(size=6.2),strip.text=element_text(size=7,face='bold'),panel.spacing=unit(3,'mm'),legend.position='right',legend.key.height=unit(3,'mm'),legend.key.width=unit(2,'mm'))
p<-(wrap_elements(full=grid.grabExpr(summary(),width=174/25.4,height=17/25.4))/heat)+plot_layout(heights=c(17,67))+plot_annotation(caption='GSVA; subtype minus others; intervals and sensitivity: Supplementary Table 5',theme=th())
loss<-function(){canvas(60,70);vt('Cost of feature reduction',1,67,7.5,T);vt('Adaptive compact − full workflow',1,61.5,6.1,T);vt(sprintf('Δ BA %.2f pp [%.2f, %.2f]',100*del$Estimate,100*del$Lower95,100*del$Upper95),1,56.5,6);xx<-function(v)6+(v+2.6)/2.9*48;vl(rep(xx(0),2),c(38,51),'#8294A2');grid.lines(unit(rep(xx(-1),2),'native'),unit(c(38,51),'native'),gp=gpar(col='#8294A2',lwd=.6,lty=2));vt('−1 pp target',xx(-1),52.2,5.7,F,'centre');vl(xx(100*c(del$Lower95,del$Upper95)),rep(44,2),INK,1.1);vp(xx(100*del$Estimate),44,1.8);for(v in c(-2,-1,0))vt(v,xx(v),35,5.7,F,'centre');vt('BA-loss target not met',30,30,6.3,T,'centre');vt('Genes selected in 25 outer fits',1,23.8,6,T);vt('Median 23 [10–51]',1,19.5,5.8);f<-ch[,.N,by=K];for(i in 1:nrow(f))for(j in 1:f$N[i])vp(7+(f$K[i]-10)/41*45,11+(j-1)*1.5,.75);vl(c(7,52),c(9,9),'#9CABBA',.4);for(v in c(10,30,51))vt(v,7+(v-10)/41*45,6.5,5.6,F,'centre');vt('17-gene expression: S6J; weights: main G',1,2,5.6);popViewport()}
for(a in list(list('Figure5E_external_programs',p,174,90),list('Figure5G_reduction_cost',loss,60,70)))for(ext in c('pdf','svg','png')){f<-file.path(ff,paste0(a[[1]],'.',ext));if(ext=='pdf')cairo_pdf(f,width=a[[3]]/25.4,height=a[[4]]/25.4,family='Arial');if(ext=='svg')svglite(f,width=a[[3]]/25.4,height=a[[4]]/25.4);if(ext=='png')agg_png(f,width=a[[3]],height=a[[4]],units='mm',res=600,background='white');if(is.function(a[[2]]))a[[2]]()else print(a[[2]]);dev.off()}
